using symbol "std:io" @print;
array Values[u32]::i64;
symbol @arena;
symbol @moved;
symbol @consume;
effect @arena <- region(4096u64);
procedure @consume() { effect @moved <- @arena; {} }
function read(values::Values)::i64 { values[0u32] }
{
 let values = alloc @arena Values(1u64, 7);
 let result = read(deref(values));
 behave @consume();
 behave @print(result);
};

