using symbol "std:io" @print;
array Values[u32]::i64;
symbol @arena;
symbol @moved;
symbol @consume;
effect @arena <- region(4096u64);
procedure @consume() { effect @moved <- @arena; {} }
{
 let values = alloc @arena Values(1u64, 7);
 let flag = values[0u32] > 0;
 if (flag) { effect @arena <- region(128u64); {} }
 else { effect @arena <- region(256u64); {} };
 behave @print(values[0u32]);
};

